using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEditor;

public static class RecoveredVehicleImporter
{
    const string InputRoot="Assets/Recovery/Vehicles";
    const string OutputRoot="Assets/RecoveredVehicles";
    [Serializable] public class Blueprint {public string model;public Node[] nodes;public MeshRef[] meshes;public TextureRef[] textures;public MaterialRef[] materials;}
    [Serializable] public class Node {public string id,name,parent,mesh,path;public Vector3 position,scale;public Quaternion rotation;public bool active,rendererEnabled=true;public int layer;public uint renderingLayerMask;public string[] materials;}
    [Serializable] public class MeshRef {public string id,file,name;}
    [Serializable] public class TextureRef {public string id,file,name;public int colorSpace,filterMode,wrapU,wrapV,wrapW,aniso,mipCount;public float mipBias;}
    [Serializable] public class MaterialRef {public string id,name,shaderName;public string[] keywords,disabledShaderPasses;public int renderQueue,lightmapFlags;public bool enableInstancing,doubleSidedGI;public ColorRef[] colors;public FloatRef[] floats;public IntRef[] ints;public TextureSlot[] textures;}
    [Serializable] public class ColorRef {public string name;public Color value;}
    [Serializable] public class FloatRef {public string name;public float value;}
    [Serializable] public class IntRef {public string name;public int value;}
    [Serializable] public class TextureSlot {public string name,texture;public Vector2 scale,offset;}
    [Serializable] public class MeshData {public string name,tangentsRawFloat32;public Vector3[] vertices,normals;public Vector4[] tangents;public Vector2[] uv,uv2;public Color[] colors;public bool colorUNorm8;public IndexGroup[] submeshes;}
    [Serializable] public class IndexGroup {public int[] indices;}
    [Serializable] public class Ports {public Port[] ports;}
    [Serializable] public class Port {public string originalShader,shaderName;public string[] keywords;}
    [Serializable] public class NativeInit {public string nodeId;public Vector3 position,scale;public Quaternion rotation;public bool active,hasRendererEnabled,rendererEnabled;}
    [Serializable] public class Motion : NativeCarControls.Motion {public string nodeId;}
    [Serializable] public class Palette {public string[] targetMaterialIds;public PaletteVariant[] variants;}
    [Serializable] public class PaletteVariant {public string name;public string[] materialIds;}
    [Serializable] public class Light {public string materialId,materialName,property,shaderName;public Color on,off;public bool flash,gradient,requiresNativeRatioCapture;}
    [Serializable] public class Wheel {public string nodeID,name,path;}
    [Serializable] public class Extra {public string type,t0Id,t1Id,rotator0Id,rotator1Id,rotatorId,translaterId;public int configID;public float duration;public Vector3 angles0,angles1,angles,pos0,pos1;public Light light;}
    [Serializable] public class RuntimeConfig {public string model,motionDurationSource;public bool nativeReady;public NativeInit[] initialization;public Motion[] motions;public Light[] lights,flashes,gradients;public Palette paint,interior;public Extra[] extras;public Wheel[] wheelVariants;public int carTypes,sideCharger,axisTrunk,configExtraSupports,configExtraDefault;public Vector3 cameraPosition,chargerPosition;public Quaternion cameraRotation;public float cameraFov,sentryScale;public GarageVehicle.Global[] globals;public string[] warnings;}
    [Serializable] public class RenderBindings {public Proxy[] renderProxies;public Drawer[] bindings;}
    [Serializable] public class Proxy {public string nodeId,path;public int mode;public Vector3[] points;}
    [Serializable] public class Drawer {public string sourceComponent,assetID,name,nodeId,meshId,materialId;public int layer,instance,submesh;public float fixMirror,cull;}
    [Serializable] public class ImportReport {public string model;public int nodes,meshes,materials,initialized,motions;public string[] warnings;}
    static T Read<T>(string path){return JsonUtility.FromJson<T>(File.ReadAllText(path));}
    static string Input(string file){return InputRoot+"/"+file;}
    static string Key(string id){return id.Replace(':','_');}
    static T Save<T>(T value,string path) where T:UnityEngine.Object {var old=AssetDatabase.LoadAssetAtPath<T>(path);if(old!=null){EditorUtility.CopySerialized(value,old);UnityEngine.Object.DestroyImmediate(value);EditorUtility.SetDirty(old);return old;}AssetDatabase.CreateAsset(value,path);return value;}
    static bool SameKeywords(string[] a,string[] b){a=a??Array.Empty<string>();b=b??Array.Empty<string>();if(a.Length!=b.Length)return false;foreach(var k in a)if(Array.IndexOf(b,k)<0)return false;return true;}
    static Shader ResolveShader(MaterialRef m,List<Port> ports){foreach(var p in ports)if(p.originalShader==m.shaderName&&SameKeywords(p.keywords,m.keywords)){var s=Shader.Find(p.shaderName);if(s!=null&&!ShaderUtil.ShaderHasError(s))return s;}if(m.shaderName=="Standard")return Shader.Find("Standard");throw new InvalidOperationException("Missing exact shader variant: "+m.shaderName+" / "+m.name+" / "+string.Join(",",m.keywords??Array.Empty<string>()));}
    static Transform Target(Dictionary<string,GameObject> nodes,string id){return !string.IsNullOrEmpty(id)&&id!="0"&&nodes.TryGetValue(id,out var go)?go.transform:null;}
    static GarageVehicle.Palette BindPalette(Palette p,Dictionary<string,Material> mats){if(p==null||p.targetMaterialIds==null)return null;var result=new GarageVehicle.Palette{targets=new Material[p.targetMaterialIds.Length],variants=new GarageVehicle.PaletteVariant[p.variants.Length]};for(int i=0;i<result.targets.Length;i++)result.targets[i]=mats[p.targetMaterialIds[i]];for(int j=0;j<p.variants.Length;j++){var v=p.variants[j];if(v.materialIds.Length!=result.targets.Length)throw new InvalidOperationException("Preset group mismatch");var dest=new GarageVehicle.PaletteVariant{name=v.name,materials=new Material[v.materialIds.Length]};for(int i=0;i<dest.materials.Length;i++)dest.materials[i]=mats[v.materialIds[i]];result.variants[j]=dest;}return result;}
    static GarageVehicle.LightBinding BindLight(Light l,Dictionary<string,Material> mats){if(l==null||string.IsNullOrEmpty(l.materialId))return null;var m=mats[l.materialId];if(!m.HasProperty(l.property))throw new InvalidOperationException("Original light property absent: "+m.name+" "+l.property);return new GarageVehicle.LightBinding{materialId=l.materialId,material=m,property=l.property,shaderName=l.shaderName,on=l.on,off=l.off,flash=l.flash,gradient=l.gradient,requiresNativeRatioCapture=l.requiresNativeRatioCapture};}
    static RecoveredLightControls.State[] BindStates(Light[] entries,Dictionary<string,Material> mats){var list=new List<RecoveredLightControls.State>();if(entries!=null)foreach(var l in entries){var binding=BindLight(l,mats);list.Add(new RecoveredLightControls.State{materialName=l.materialName,material=binding.material,property=l.property,on=l.on,off=l.off,gradient=l.gradient});}return list.ToArray();}

    static string ExtraLabel(int id){switch(id){case 1:return "行李架";case 2:return "行李架灯";case 4:return "拖钩";case 8:return "天窗";case 16:return "尾翼";case 32:return "云台";case 64:return "雷达";default:return id.ToString();}}
    [MenuItem("Deepal Recovery/Garage Import All Vehicles")]
    public static void ImportAll(){foreach(var dir in Directory.GetDirectories(InputRoot)){if(Path.GetFileName(dir)=="common"||!File.Exists(dir+"/blueprint.json"))continue;var id=Path.GetFileName(dir);if(File.Exists(OutputRoot+"/"+id+"/Vehicle.prefab")&&File.Exists(OutputRoot+"/"+id+"/import-report.json")){Debug.Log("Reusing verified imported prefab "+id);continue;}ImportVehicle(id);}AssetDatabase.SaveAssets();}
    public static void ImportVehicle(string id)
    {
        var source=Read<Blueprint>(InputRoot+"/"+id+"/blueprint.json");var common=Read<Blueprint>(InputRoot+"/common/blueprint.json");var config=Read<RuntimeConfig>(InputRoot+"/"+id+"/runtime-config.json");if(!config.nativeReady)throw new InvalidOperationException("Original native initialization missing: "+id);
        var render=Read<RenderBindings>(InputRoot+"/"+id+"/render-bindings.json");var generated=OutputRoot+"/"+id;Directory.CreateDirectory(generated+"/Meshes");Directory.CreateDirectory(generated+"/Materials");AssetDatabase.Refresh();
        var ports=new List<Port>();foreach(var p in Directory.GetFiles("Assets","ports.json",SearchOption.AllDirectories)){var parsed=Read<Ports>(p);if(parsed?.ports!=null)ports.AddRange(parsed.ports);}
        var meshes=new Dictionary<string,Mesh>();var refs=new List<MeshRef>(common.meshes);refs.AddRange(source.meshes);
        foreach(var entry in refs){var d=Read<MeshData>(Input(entry.file));var mesh=new Mesh{name=d.name,indexFormat=d.vertices.Length>65535?IndexFormat.UInt32:IndexFormat.UInt16};mesh.vertices=d.vertices;
            if(d.normals!=null&&d.normals.Length==d.vertices.Length)mesh.normals=d.normals;else if(d.normals!=null&&d.normals.Length>0)throw new InvalidOperationException("Malformed original normal channel: "+entry.id);
            if(!string.IsNullOrEmpty(d.tangentsRawFloat32)){var bytes=File.ReadAllBytes(Input(d.tangentsRawFloat32));if(bytes.Length!=d.vertices.Length*16)throw new InvalidOperationException("Raw tangent byte size mismatch");var ts=new Vector4[d.vertices.Length];for(int i=0;i<ts.Length;i++)ts[i]=new Vector4(BitConverter.ToSingle(bytes,i*16),BitConverter.ToSingle(bytes,i*16+4),BitConverter.ToSingle(bytes,i*16+8),BitConverter.ToSingle(bytes,i*16+12));mesh.tangents=ts;}
            else if(d.tangents!=null&&d.tangents.Length==d.vertices.Length)mesh.tangents=d.tangents;
            if(d.uv!=null&&d.uv.Length==d.vertices.Length)mesh.uv=d.uv;if(d.uv2!=null&&d.uv2.Length==d.vertices.Length)mesh.uv2=d.uv2;
            if(d.colors!=null&&d.colors.Length==d.vertices.Length){if(d.colorUNorm8){var c=new Color32[d.colors.Length];for(int i=0;i<c.Length;i++)c[i]=new Color32((byte)d.colors[i].r,(byte)d.colors[i].g,(byte)d.colors[i].b,(byte)d.colors[i].a);mesh.colors32=c;}else mesh.colors=d.colors;}
            mesh.subMeshCount=d.submeshes.Length;for(int i=0;i<d.submeshes.Length;i++)mesh.SetTriangles(d.submeshes[i].indices,i,false);mesh.RecalculateBounds();meshes[entry.id]=Save(mesh,generated+"/Meshes/"+Key(entry.id)+".asset");}
        var textures=new Dictionary<string,Texture2D>();var texrefs=new List<TextureRef>(common.textures);texrefs.AddRange(source.textures);
        foreach(var t in texrefs){var path=Input(t.file);var importer=(TextureImporter)AssetImporter.GetAtPath(path);if(importer==null)throw new InvalidOperationException("Texture source missing: "+path);bool changed=importer.sRGBTexture!=(t.colorSpace==1)||importer.wrapModeU!=(TextureWrapMode)t.wrapU||importer.wrapModeV!=(TextureWrapMode)t.wrapV||importer.wrapModeW!=(TextureWrapMode)t.wrapW||importer.filterMode!=(FilterMode)t.filterMode||importer.anisoLevel!=t.aniso||importer.mipmapEnabled!=(t.mipCount>1)||importer.textureCompression!=TextureImporterCompression.Uncompressed||importer.npotScale!=TextureImporterNPOTScale.None||importer.maxTextureSize!=8192;
            if(changed){importer.sRGBTexture=t.colorSpace==1;importer.wrapModeU=(TextureWrapMode)t.wrapU;importer.wrapModeV=(TextureWrapMode)t.wrapV;importer.wrapModeW=(TextureWrapMode)t.wrapW;importer.filterMode=(FilterMode)t.filterMode;importer.anisoLevel=t.aniso;importer.mipmapEnabled=t.mipCount>1;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.npotScale=TextureImporterNPOTScale.None;importer.maxTextureSize=8192;importer.SaveAndReimport();}textures[t.id]=AssetDatabase.LoadAssetAtPath<Texture2D>(path);textures[t.id].mipMapBias=t.mipBias;EditorUtility.SetDirty(textures[t.id]);}
        var materials=new Dictionary<string,Material>();var matrefs=new List<MaterialRef>(common.materials);matrefs.AddRange(source.materials);
        foreach(var entry in matrefs){var shader=ResolveShader(entry,ports);var mat=new Material(shader){name=entry.name,renderQueue=entry.renderQueue,enableInstancing=entry.enableInstancing,doubleSidedGI=entry.doubleSidedGI,globalIlluminationFlags=(MaterialGlobalIlluminationFlags)entry.lightmapFlags};foreach(var c in entry.colors??Array.Empty<ColorRef>())if(mat.HasProperty(c.name))mat.SetColor(c.name,c.value);foreach(var f in entry.floats??Array.Empty<FloatRef>()){int p=shader.FindPropertyIndex(f.name);if(p>=0){var type=shader.GetPropertyType(p);if(type==ShaderPropertyType.Float||type==ShaderPropertyType.Range||type==ShaderPropertyType.Int)mat.SetFloat(f.name,f.value);}}foreach(var f in entry.ints??Array.Empty<IntRef>())if(mat.HasProperty(f.name))mat.SetInteger(f.name,f.value);foreach(var t in entry.textures??Array.Empty<TextureSlot>())if(mat.HasProperty(t.name)&&textures.TryGetValue(t.texture,out var tx)){mat.SetTexture(t.name,tx);mat.SetTextureScale(t.name,t.scale);mat.SetTextureOffset(t.name,t.offset);}foreach(var pass in entry.disabledShaderPasses??Array.Empty<string>())mat.SetShaderPassEnabled(pass,false);materials[entry.id]=Save(mat,generated+"/Materials/"+Key(entry.id)+".mat");}
        var root=new GameObject("Vehicle_"+id);try{
            var nodes=new Dictionary<string,GameObject>();foreach(var n in source.nodes)nodes[n.id]=new GameObject(n.name);
            foreach(var n in source.nodes){var go=nodes[n.id];go.transform.SetParent(nodes.TryGetValue(n.parent,out var parent)?parent.transform:root.transform,false);go.transform.localPosition=n.position;go.transform.localRotation=n.rotation;go.transform.localScale=n.scale;go.layer=n.layer;go.SetActive(n.active);if(!string.IsNullOrEmpty(n.mesh)){if(!meshes.TryGetValue(n.mesh,out var mesh))throw new InvalidOperationException("Missing original mesh "+n.mesh);go.AddComponent<MeshFilter>().sharedMesh=mesh;var mr=go.AddComponent<MeshRenderer>();mr.enabled=n.rendererEnabled;mr.renderingLayerMask=n.renderingLayerMask;var array=new Material[n.materials.Length];for(int i=0;i<array.Length;i++)array[i]=materials[n.materials[i]];mr.sharedMaterials=array;}}
            foreach(var n in config.initialization){if(!nodes.TryGetValue(n.nodeId,out var go))throw new InvalidOperationException("Native init node missing "+n.nodeId);go.transform.localPosition=n.position;go.transform.localRotation=n.rotation;go.transform.localScale=n.scale;go.SetActive(n.active);if(n.hasRendererEnabled){var r=go.GetComponent<Renderer>();if(r!=null)r.enabled=n.rendererEnabled;}}
            var asset=root.AddComponent<GarageVehicle>();asset.model=id;asset.label=id.ToUpperInvariant().Replace("_"," · ");asset.motionDurationSource=config.motionDurationSource;asset.carTypes=config.carTypes;asset.sideCharger=config.sideCharger;asset.axisTrunk=config.axisTrunk;asset.configExtraSupports=config.configExtraSupports;asset.configExtraDefault=config.configExtraDefault;asset.cameraPosition=config.cameraPosition;asset.cameraRotation=config.cameraRotation;asset.cameraFov=config.cameraFov;asset.chargerPosition=config.chargerPosition;asset.sentryScale=config.sentryScale;asset.globals=config.globals;asset.evidenceWarnings=config.warnings;
            var controls=root.AddComponent<NativeCarControls>();var doors=new List<NativeCarControls.DoorBinding>();var windows=new List<NativeCarControls.DoorBinding>();foreach(var motion in config.motions){var target=Target(nodes,motion.nodeId);if(target==null)throw new InvalidOperationException("Motion binding missing "+motion.name);if(motion.name=="trunk"){controls.trunk=motion;controls.trunkTransform=target;}else if(motion.name.StartsWith("door"))doors.Add(new NativeCarControls.DoorBinding{motion=motion,target=target});else if(motion.name.StartsWith("window"))windows.Add(new NativeCarControls.DoorBinding{motion=motion,target=target});}controls.doors=doors.ToArray();controls.windows=windows.ToArray();asset.controls=controls;
            var lights=root.AddComponent<RecoveredLightControls>();lights.states=BindStates(config.lights,materials);lights.flashes=BindStates(config.flashes,materials);asset.lights=lights;var gradients=new List<GarageVehicle.LightBinding>();foreach(var l in config.gradients??Array.Empty<Light>())gradients.Add(BindLight(l,materials));asset.gradients=gradients.ToArray();asset.paint=BindPalette(config.paint,materials);asset.interior=BindPalette(config.interior,materials);
            var wheels=new List<GarageVehicle.Wheel>();foreach(var w in config.wheelVariants??Array.Empty<Wheel>()){var raw=Array.Find(source.nodes,n=>n.id==w.nodeID);wheels.Add(new GarageVehicle.Wheel{name=w.name,nodeId=w.nodeID,target=Target(nodes,w.nodeID),originalPosition=raw.position});}asset.wheels=wheels.ToArray();asset.wheelNodes=new Transform[wheels.Count];asset.wheelLabels=new string[wheels.Count];for(int i=0;i<wheels.Count;i++){asset.wheelNodes[i]=wheels[i].target;asset.wheelLabels[i]=wheels[i].name;}
            var extras=new List<GarageVehicle.Extra>();foreach(var e in config.extras??Array.Empty<Extra>())extras.Add(new GarageVehicle.Extra{type=e.type,configID=e.configID,duration=e.duration,t0=Target(nodes,e.t0Id),t1=Target(nodes,e.t1Id),rotator0=Target(nodes,e.rotator0Id),rotator1=Target(nodes,e.rotator1Id),rotator=Target(nodes,e.rotatorId),translater=Target(nodes,e.translaterId),angles0=e.angles0,angles1=e.angles1,angles=e.angles,pos0=e.pos0,pos1=e.pos1,light=BindLight(e.light,materials)});asset.extras=extras.ToArray();foreach(var e in asset.extras){e.label=ExtraLabel(e.configID);e.closed0=e.rotator0!=null?e.rotator0.localRotation:Quaternion.identity;e.closed1=e.rotator1!=null?e.rotator1.localRotation:Quaternion.identity;e.closedRotation=e.rotator!=null?e.rotator.localRotation:Quaternion.identity;e.formulaVerified=false;}
            var proxies=new List<RecoveredBloomRegion.Proxy>();foreach(var p in render.renderProxies)proxies.Add(new RecoveredBloomRegion.Proxy{nodeId=p.nodeId,target=Target(nodes,p.nodeId),mirror=p.mode,points=p.points});asset.proxies=proxies.ToArray();
            var drawers=new List<GarageVehicle.Drawer>();foreach(var d in render.bindings)drawers.Add(new GarageVehicle.Drawer{sourceComponent=d.sourceComponent,assetID=d.assetID,name=d.name,nodeId=d.nodeId,source=Target(nodes,d.nodeId),mesh=meshes[d.meshId],material=materials[d.materialId],layer=d.layer,instance=d.instance,submesh=d.submesh,fixMirror=d.fixMirror,cull=d.cull});asset.drawers=drawers.ToArray();var collision=new List<RecoveredCollisionSurface.Binding>();var reflection=new List<GarageVehicle.Drawer>();foreach(var d in drawers){if(d.layer==9)collision.Add(new RecoveredCollisionSurface.Binding{source=d.source,mesh=d.mesh,material=d.material,submesh=d.submesh});if(d.layer==0)reflection.Add(d);}asset.collisionBindings=collision.ToArray();asset.reflectionBindings=reflection.ToArray();
            // Drawers remain explicit bindings: the garage renderer owns their reflection/collision pass lifecycle.
            PrefabUtility.SaveAsPrefabAsset(root,generated+"/Vehicle.prefab");File.WriteAllText(generated+"/import-report.json",JsonUtility.ToJson(new ImportReport{model=id,nodes=nodes.Count,meshes=meshes.Count,materials=materials.Count,initialized=config.initialization.Length,motions=config.motions.Length,warnings=config.warnings},true));AssetDatabase.SaveAssets();Debug.Log("Imported original native vehicle prefab "+id+" / motions "+config.motions.Length);
        }finally{UnityEngine.Object.DestroyImmediate(root);}
    }
}
